create type public.submission_method as enum ('api','email','portal','unknown_tbd');

create table public.funder_master (
  id uuid primary key default gen_random_uuid(),
  funder_name text not null unique,
  positions text,
  states text,
  min_monthly_revenue numeric(12,2),
  min_time_in_business_months int,
  min_fico int,
  max_funding numeric(12,2),
  payment_frequency text,
  required_docs text,
  industry_yes text,
  industry_maybe text,
  industry_no text,
  notes text,
  submission_method public.submission_method not null default 'unknown_tbd',
  submission_endpoint text,
  matrix_row jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.funder_routing_inputs (
  id uuid primary key default gen_random_uuid(),
  input_name text not null unique,
  example_value text,
  rule_notes text,
  sort_order int not null,
  created_at timestamptz not null default now()
);

create table public.funder_legend_rules (
  id uuid primary key default gen_random_uuid(),
  legend_key text not null unique,
  meaning text not null,
  created_at timestamptz not null default now()
);
alter table public.funder_master enable row level security;
alter table public.funder_routing_inputs enable row level security;
alter table public.funder_legend_rules enable row level security;
create policy "funder_master_admin_read" on public.funder_master for select using (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')
);
create policy "funder_routing_inputs_admin_read" on public.funder_routing_inputs for select using (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')
);
create policy "funder_legend_rules_admin_read" on public.funder_legend_rules for select using (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')
);
